import { useCallback, useEffect, useMemo, useState } from "react";
import { useParams } from "react-router";

/**
 * Public, no-auth approval page for client-side email recipients.
 *
 * Lands here from the `Review & approve` button in `rmm_assigned_request`
 * emails (and from the `Decline` button, which appends `#decline` to the
 * same URL so we default-open the decline form). The path is
 * `/approve/:token` where `:token` is a `TimestampSigner`-signed payload
 * generated by `events.views.make_approval_token` on the backend.
 *
 * Why this exists: the older flow pointed the email button at
 * `/approvals?request=<id>`, which routes through `AdminOnly` + a
 * JWT-protected GraphQL query. For any client whose Spark account didn't
 * survive the admin guard (or who didn't have an account at all), the
 * page blanked out (an uncaught useLazyLoadQuery error behind a Suspense
 * boundary with no ErrorBoundary). This page never touches the auth
 * stack — the token *is* the auth — so it works for true external
 * recipients, RMMs from a different tenant, and freshly-onboarded
 * clients alike.
 */

type RequestDetail = {
  id: number;
  displayId: string;
  tenantName: string;
  accountName: string;
  address: string;
  date: string;
  startTime: string;
  endTime: string;
  activationType: string;
  distributor: string;
  products: string[];
  baCount: number | null;
  requestorName: string;
  requestorEmail: string;
  status: { slug: string; name: string };
  declineReason: string;
};

type ApprovalResponse = {
  request: RequestDetail;
  recipientEmail: string;
  alreadyResolved?: boolean;
  result?: "approved" | "declined";
};

type ApiError = {
  error: string;
  message: string;
};

// Derive the API base from the GraphQL endpoint env var so we never have
// to wire a second env var just for this one REST endpoint. (Vite inlines
// import.meta.env at build time, so this happens once per build, not at
// runtime.)
function publicApprovalBaseUrl(): string {
  const graphql = import.meta.env.VITE_GRAPHQL_ENDPOINT as string | undefined;
  if (!graphql) {
    // Fallback — keeps dev/preview builds usable even if env wasn't set.
    return "/api/public/approval";
  }
  try {
    const url = new URL(graphql);
    return `${url.origin}/api/public/approval`;
  } catch {
    return "/api/public/approval";
  }
}

const ROW_LABEL_CLS = "mono text-[10px] font-semibold uppercase tracking-[0.16em]";
const ROW_VALUE_CLS = "text-sm font-medium";

const PublicApprove: React.FC = () => {
  const { token } = useParams<{ token: string }>();
  const [data, setData] = useState<ApprovalResponse | null>(null);
  const [err, setErr] = useState<ApiError | null>(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [showDecline, setShowDecline] = useState(false);
  const [reason, setReason] = useState("");
  const [doneState, setDoneState] = useState<"approved" | "declined" | null>(null);

  const baseUrl = useMemo(publicApprovalBaseUrl, []);
  const endpoint = token ? `${baseUrl}/${encodeURIComponent(token)}` : "";

  // Default-open the decline form when the email's "Decline" button was
  // clicked — that link is `…/approve/<token>#decline`.
  useEffect(() => {
    if (typeof window !== "undefined" && window.location.hash === "#decline") {
      setShowDecline(true);
    }
  }, []);

  // Fetch request details on mount.
  useEffect(() => {
    if (!endpoint) return;
    let cancelled = false;
    setLoading(true);
    fetch(endpoint)
      .then(async (res) => {
        const json = await res.json().catch(() => ({}));
        if (cancelled) return;
        if (!res.ok) {
          setErr({
            error: json.error || "fetch_failed",
            message: json.message || `Server returned ${res.status}.`,
          });
          setData(null);
        } else {
          setData(json as ApprovalResponse);
          setErr(null);
          // If the backend tells us the request was already resolved,
          // surface a "done" state immediately so the page doesn't
          // pretend the buttons still do anything.
          if ((json as ApprovalResponse).alreadyResolved) {
            const slug = (json as ApprovalResponse).request?.status?.slug;
            if (slug === "approved" || slug === "declined") setDoneState(slug);
          }
        }
      })
      .catch((e: Error) => {
        if (cancelled) return;
        setErr({ error: "network", message: e.message || "Network error." });
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [endpoint]);

  const submit = useCallback(
    async (action: "approve" | "decline") => {
      if (!endpoint || submitting) return;
      if (action === "decline" && !reason.trim()) {
        setErr({
          error: "reason_required",
          message:
            "Please share a quick reason so the requestor knows what to change.",
        });
        return;
      }
      setSubmitting(true);
      setErr(null);
      try {
        const res = await fetch(endpoint, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            action,
            reason: action === "decline" ? reason.trim() : undefined,
          }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok) {
          setErr({
            error: json.error || "submit_failed",
            message: json.message || `Server returned ${res.status}.`,
          });
        } else {
          setData(json as ApprovalResponse);
          setDoneState(action === "approve" ? "approved" : "declined");
        }
      } catch (e) {
        setErr({
          error: "network",
          message: (e as Error).message || "Network error.",
        });
      } finally {
        setSubmitting(false);
      }
    },
    [endpoint, reason, submitting],
  );

  // ── render ───────────────────────────────────────────────────────────

  // Loading
  if (loading) {
    return (
      <Shell>
        <p className="text-sm text-stone-500">Loading request…</p>
      </Shell>
    );
  }

  // Hard errors (expired / invalid / 404 / network) with no data to fall
  // back on. We pull the friendly message straight from the backend so
  // the same string appears in logs and on the screen.
  if (err && !data) {
    return (
      <Shell>
        <h1 className="display text-2xl font-bold mb-3" style={{ letterSpacing: "-0.025em", color: "#14160f" }}>
          {err.error === "expired" ? "This link has expired." : "We couldn't open this link."}
        </h1>
        <p className="text-sm mb-6" style={{ color: "rgba(20, 22, 15, 0.74)" }}>{err.message}</p>
        <p className="text-xs" style={{ color: "rgba(20, 22, 15, 0.58)" }}>
          Ask the requestor or your Ignite contact to resend the approval email.
        </p>
      </Shell>
    );
  }

  if (!data) return null; // shouldn't happen, but keeps TS happy

  const req = data.request;

  // Already-resolved or just-resolved success state.
  if (doneState) {
    return (
      <Shell>
        <p
          className="mono text-[10px] font-semibold uppercase tracking-[0.18em] mb-2"
          style={{ color: doneState === "approved" ? "#2b4c08" : "#a8340f" }}
        >
          {doneState === "approved" ? "Request approved" : "Request declined"}
        </p>
        <h1
          className="display text-2xl font-bold mb-3"
          style={{ letterSpacing: "-0.025em", color: "#14160f" }}
        >
          {doneState === "approved"
            ? "You're all set — Ignite is staffing it."
            : "Thanks for the heads-up."}
        </h1>
        <p className="text-sm mb-6 leading-relaxed" style={{ color: "rgba(20, 22, 15, 0.74)" }}>
          {doneState === "approved"
            ? `${req.accountName} on ${req.date} has been marked approved. The requestor and the Ignite team have been notified.`
            : `${req.accountName} on ${req.date} has been declined. The requestor (${req.requestorEmail || "—"}) was notified along with your reason.`}
        </p>
        {req.declineReason && doneState === "declined" && (
          <div
            className="rounded-xl p-4 text-sm"
            style={{ background: "#f6f6f2", border: "1px solid #dcddd5", color: "#14160f" }}
          >
            <p className="mono text-[10px] font-semibold uppercase tracking-[0.16em] mb-1" style={{ color: "rgba(20, 22, 15, 0.58)" }}>
              Reason
            </p>
            {req.declineReason}
          </div>
        )}
        <p className="mt-6 text-xs" style={{ color: "rgba(20, 22, 15, 0.58)" }}>
          You can safely close this tab.
        </p>
      </Shell>
    );
  }

  // Live action state — render request details + buttons.
  return (
    <Shell>
      <p className="mono text-[10px] font-semibold uppercase tracking-[0.18em] mb-1" style={{ color: "rgba(20, 22, 15, 0.58)" }}>
        {req.tenantName ? `${req.tenantName} · ` : ""}NEEDS YOUR APPROVAL
      </p>
      <h1
        className="display text-2xl sm:text-3xl font-bold mb-1"
        style={{ letterSpacing: "-0.025em", color: "#14160f" }}
      >
        {req.accountName || "(no account name)"}
      </h1>
      <p className="text-sm mb-6" style={{ color: "rgba(20, 22, 15, 0.72)" }}>
        Submitted by{" "}
        <span className="font-semibold" style={{ color: "#14160f" }}>{req.requestorName || "—"}</span>
        {req.requestorEmail ? (
          <>
            {" "}
            ·{" "}
            <a
              href={`mailto:${req.requestorEmail}`}
              className="underline"
              style={{ color: "#14160f" }}
            >
              {req.requestorEmail}
            </a>
          </>
        ) : null}
      </p>

      <div
        className="rounded-xl overflow-hidden divide-y"
        style={{ border: "1px solid #dcddd5", background: "#ffffff", borderColor: "#dcddd5" }}
      >
        <Row label="Request ID" value={req.displayId} />
        <Row label="Address" value={req.address || "—"} />
        <Row
          label="When"
          value={
            req.date
              ? `${req.date}${
                  req.startTime || req.endTime
                    ? ` · ${req.startTime} – ${req.endTime}`
                    : ""
                }`
              : "—"
          }
        />
        <Row label="Activation type" value={req.activationType || "—"} />
        <Row label="Distributor" value={req.distributor || "—"} />
        <Row
          label="Products"
          value={
            req.products && req.products.length > 0
              ? req.products.join(", ")
              : "—"
          }
        />
        <Row
          label="BA count"
          value={req.baCount != null ? String(req.baCount) : "—"}
        />
      </div>

      {err && (
        <div
          className="mt-4 rounded-xl p-3 text-sm font-medium"
          style={{
            background: "rgba(210, 72, 27, 0.08)",
            border: "1px solid rgba(210, 72, 27, 0.28)",
            color: "#a8340f",
          }}
        >
          {err.message}
        </div>
      )}

      <div className="mt-6 flex flex-wrap gap-2.5 items-center">
        <button
          type="button"
          onClick={() => submit("approve")}
          disabled={submitting}
          className="px-5 py-2.5 rounded-lg text-sm font-semibold transition cursor-pointer"
          style={{
            background: "#14160f",
            color: "#ffffff",
            opacity: submitting ? 0.5 : 1,
          }}
        >
          {submitting ? "Working…" : "Review & approve →"}
        </button>
        <button
          type="button"
          onClick={() => setShowDecline((v) => !v)}
          disabled={submitting}
          className="px-4 py-2.5 rounded-lg text-sm font-semibold transition cursor-pointer"
          style={{
            background: "#ffffff",
            color: "#14160f",
            border: "1px solid #dcddd5",
            opacity: submitting ? 0.5 : 1,
          }}
        >
          {showDecline ? "Cancel decline" : "Decline"}
        </button>
      </div>

      {showDecline && (
        <div
          className="mt-4 rounded-xl p-4"
          style={{ border: "1px solid #dcddd5", background: "#f6f6f2" }}
        >
          <label className="block mono text-[10px] font-semibold uppercase tracking-[0.16em] mb-2" style={{ color: "rgba(20, 22, 15, 0.62)" }}>
            What's the reason?
          </label>
          <textarea
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            rows={3}
            placeholder="e.g. Different store — please use 2401 W Ave instead, same date"
            className="w-full rounded-lg p-3 text-sm focus:outline-none"
            style={{ background: "#ffffff", border: "1px solid #dcddd5", color: "#14160f" }}
          />
          <p className="text-xs mt-2" style={{ color: "rgba(20, 22, 15, 0.58)" }}>
            This goes back to {req.requestorEmail || "the requestor"} automatically.
          </p>
          <button
            type="button"
            onClick={() => submit("decline")}
            disabled={submitting || !reason.trim()}
            className="mt-3 px-4 py-2 rounded-lg text-sm font-semibold transition cursor-pointer"
            style={{
              background: "#a8340f",
              color: "#ffffff",
              opacity: submitting || !reason.trim() ? 0.4 : 1,
            }}
          >
            {submitting ? "Sending…" : "Send decline"}
          </button>
        </div>
      )}

      <p className="mt-8 text-xs" style={{ color: "rgba(20, 22, 15, 0.5)" }}>
        Spark by Ignite · This link is private to {data.recipientEmail || "you"}.
      </p>
    </Shell>
  );
};

const Row: React.FC<{ label: string; value: string }> = ({ label, value }) => (
  <div
    className="px-4 py-3 flex flex-col sm:flex-row sm:items-baseline gap-1 sm:gap-4"
    style={{ borderColor: "#ecece6" }}
  >
    <span className={ROW_LABEL_CLS + " sm:w-36 shrink-0"} style={{ color: "rgba(20, 22, 15, 0.56)" }}>
      {label}
    </span>
    <span className={ROW_VALUE_CLS + " tab-num"} style={{ color: "#14160f" }}>
      {value}
    </span>
  </div>
);

const Shell: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div
    data-theme="spark-v2"
    data-spark-mode="light"
    className="min-h-screen"
    style={{ background: "#f6f6f2", color: "#14160f", colorScheme: "light" }}
  >
    <div className="max-w-2xl mx-auto px-5 py-10 sm:py-12">
      <div className="mb-7">
        <a href="https://www.igniteproductions.co/" style={{ textDecoration: "none" }}>
          <img
            src="/legal/spark-logo.png"
            alt="Spark by Ignite"
            style={{ height: 26, width: "auto" }}
          />
        </a>
      </div>
      <div
        className="rounded-xl p-6 sm:p-8"
        style={{ background: "#ffffff", border: "1px solid #dcddd5" }}
      >
        {children}
      </div>
      <p className="mt-6 text-center text-xs" style={{ color: "rgba(20, 22, 15, 0.52)" }}>
        Questions?{" "}
        <a
          className="underline"
          href="mailto:staffing@igniteproductions.co"
          style={{ color: "rgba(20, 22, 15, 0.74)" }}
        >
          staffing@igniteproductions.co
        </a>
      </p>
    </div>
  </div>
);

export default PublicApprove;
